function makeCounter() {
  let count = 0;
  return (code) => eval(code);
}

const run = makeCounter();
run("count += 2");
console.log(run("count"));

const loose = new Function(
  "return typeof this;",
);
const strict = new Function(
  '"use strict"; return typeof this;',
);
console.log(loose(), strict());
console.log(run("typeof makeCounter"));
